import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0037: App-wide memory provider and explicit Pen banks","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0037-app-wide-memory-provider-and-pen-banks.md","filePath":"adrs/0037-app-wide-memory-provider-and-pen-banks.md","lastUpdated":1789092097000}`),u={name:`adrs/0037-app-wide-memory-provider-and-pen-banks.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[14]||=a(`<h1 id="adr-0037-app-wide-memory-provider-and-explicit-pen-banks" tabindex="-1">ADR-0037: App-wide memory provider and explicit Pen banks <a class="header-anchor" href="#adr-0037-app-wide-memory-provider-and-explicit-pen-banks" aria-label="Permalink to “ADR-0037: App-wide memory provider and explicit Pen banks”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-04 · Refines provider routing in <a href="/adrs/0005-memory-architecture">ADR-0005</a>, <a href="/adrs/0033-exclusive-pen-and-global-memory-scopes">ADR-0033</a>, and <a href="/adrs/0036-native-skills-and-hindsight-lifecycle">ADR-0036</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[2]||=i(`The first M6 configuration model exposed both a Global provider and a default provider for new `,-1),r(m,{term:`pen`},{default:n(()=>[...l[0]||=[i(`Pens`,-1)]]),_:1}),l[3]||=i(`. Pen pages could then select another provider. This made the product appear to have two application defaults even though a user chooses one storage system for GOAT. It also made `,-1),r(m,{term:`hindsight`},{default:n(()=>[...l[1]||=[i(`Hindsight`,-1)]]),_:1}),l[4]||=i(` ambiguous: configuring one server and Global bank did not explain when or how a Pen got an isolated bank.`,-1)]),l[15]||=c(`p`,null,`Global and Pen memory still need strict isolation. A local provider naturally has separate Global and Pen directories. Hindsight instead has one server with many banks. Requiring users to configure the same server repeatedly would duplicate credentials and connection health, while silently using the Global bank for every Pen would violate the isolation promised by ADR-0033.`,-1),l[16]||=c(`p`,null,`Existing provider bindings and data must remain recoverable. Changing a provider is not permission to copy, merge, rename, or delete either local files or server banks.`,-1),l[17]||=c(`h2`,{id:`decision`,tabindex:`-1`},[i(`Decision `),c(`a`,{class:`header-anchor`,href:`#decision`,"aria-label":`Permalink to “Decision”`},`​`)],-1),c(`p`,null,[l[7]||=i(`GOAT has one app-wide active memory provider. `,-1),r(m,{term:`memory`},{default:n(()=>[...l[5]||=[i(`Memory`,-1)]]),_:1}),l[8]||=i(` Settings selects Markdown, `,-1),r(m,{term:`llm-wiki`},{default:n(()=>[...l[6]||=[i(`LLM Wiki`,-1)]]),_:1}),l[9]||=i(`, or one direct Hindsight service and Global bank. There is no separate new-Pen default and no provider picker on a Pen.`,-1)]),l[18]||=a(`<p>The master Memory switch remains a hard application-wide gate. Under that gate, every Pen has an explicit enabled state:</p><ul><li>A Pen without a binding is off. Creating a Pen does not create storage or perform network work.</li><li>Enabling a Pen binds it to the current app-wide provider.</li><li>Disabling a Pen preserves its binding and history without reading, writing, or deleting data.</li><li>Changing the app-wide provider performs no Pen network or file mutation. A Pen whose preserved binding belongs to another provider appears off until the user explicitly enables it for the current provider. Switching back can resume the preserved binding.</li></ul><p>For local providers, explicit Pen enablement routes to that Pen&#39;s existing provider-specific local directory. Global memory remains exclusive to chats outside a Pen.</p><p>For Hindsight, one direct service record owns the server URL, optional credential, health, and selected Global bank. Enabling Hindsight for a Pen ensures a dedicated bank on that service using:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0" dir="ltr"><code><span class="line"><span>goat-&lt;safe-pen-name&gt;-&lt;full-lowercase-pen-uuid&gt;</span></span></code></pre></div><p>The safe name is ASCII lowercase, separators collapse to hyphens, and the name is bounded so the complete bank ID is at most 128 bytes. An empty result uses <code>pen</code>. The UUID is the durable identity, so two Pens with the same display name cannot collide. Once a route exists, renaming the Pen does not rename its bank.</p><p>Provisioning is create-or-reuse and occurs only after the explicit Pen enable action. A new bank receives GOAT&#39;s bounded starter template. An existing bank with that deterministic ID is reused and never overwritten by the starter template. GOAT then validates the bank-scoped runtime contract before persisting the enabled binding. A failed create or validation leaves the Pen disabled.</p><p>Pen route records contain only the direct service provider ID and bank ID. They do not duplicate the URL or credential. They are internal routing records and do not appear as additional providers in Settings. Removing Hindsight removes GOAT&#39;s local service and route configuration and credential but never deletes server banks.</p><p>Schema 1&#39;s <code>defaultPenProviderID</code> remains on disk as a compatibility field until a separately designed configuration migration removes it. GOAT keeps it synchronized with the app-wide provider, but it has no independent UI or runtime semantics.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The provider choice is consistent throughout the app and the redundant new-Pen default is gone.</li><li>Pen memory activation is deliberate and does not cause hidden work at Pen creation or app launch.</li><li>Hindsight gets the same Global/Pen isolation model as local providers without duplicating its service configuration.</li><li>Existing data remains untouched. Rebinding selects a future read/write destination; it is not a migration.</li><li>A server may retain an orphaned GOAT-created bank after local configuration removal. This is the safe result because GOAT exposes no destructive Hindsight operation.</li><li>Deterministic provisioning adds a bounded control-plane call to the first explicit Hindsight enable action for each Pen.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p><strong>Keep a new-Pen default.</strong> Rejected because it duplicates the app-wide provider selection and makes a newly created Pen look enabled before the user has opted into its memory lifecycle.</p>`,13),c(`p`,null,[l[11]||=c(`strong`,null,`Use the Global Hindsight bank for every Pen.`,-1),l[12]||=i(` Rejected because unrelated Pen `,-1),r(m,{term:`context-window`},{default:n(()=>[...l[10]||=[i(`context`,-1)]]),_:1}),l[13]||=i(` would share one corpus and violate exclusive scope semantics.`,-1)]),l[19]||=c(`p`,null,[c(`strong`,null,`Ask for a bank on every Pen.`),i(` Rejected because repeated setup is noisy and easy to misconfigure. The deterministic bank remains inspectable on the Pen and in Hindsight.`)],-1),l[20]||=c(`p`,null,[c(`strong`,null,`Create every Pen bank when Hindsight is configured.`),i(` Rejected because a provider selection would perform surprising network writes for Pens that may never use memory.`)],-1),l[21]||=c(`p`,null,[c(`strong`,null,`Immediately remove the schema 1 compatibility field.`),i(` Rejected for this slice because doing so requires a configuration migration with its own crash-safety and rollback contract. Hiding it from product semantics resolves the redundancy without risking existing configuration.`)],-1)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};